import {
  ActivityFeed,
  DangerZone,
  DescriptionListCard,
  FormSection,
  PageHeader,
  StatusTimeline,
  type ActivityItem,
  type DangerZoneAction,
  type DescriptionItem,
  type PageChromeAction,
  type PageHeaderMetaItem,
  type StatusEvent,
} from '@gntik-ai/blocks';
import { FileText, RotateCw } from '@gntik-ai/icons';
import {
  Button,
  Field,
  FieldDescription,
  FieldLabel,
  Grid,
  Input,
  Page,
  Section,
  Stack,
  Tabs,
  TabsList,
  TabsPanel,
  TabsTab,
  Textarea,
  type BreadcrumbItem,
} from '@gntik-ai/ui';
import { useState } from 'react';
import { ConsoleShell, type ConsoleShellProps } from '../shared/ConsoleShell';
import {
  detailActivity,
  detailBreadcrumbs,
  detailDangerActions,
  detailEvents,
  detailItems,
  detailMeta,
  detailResource,
  type ResourceSettings,
} from './data';

export type ResourceDetailTab = 'overview' | 'activity' | 'settings';

export interface ResourceDetailProps {
  name: string;
  description: string;
  /** StatusTag key next to the title. */
  status: string;
  breadcrumbs: BreadcrumbItem[];
  meta: PageHeaderMetaItem[];
  actions: PageChromeAction[];
  details: readonly DescriptionItem[];
  /** Title of the Overview details card (default "Configuration"). */
  overviewTitle: string;
  /** Description of the Overview details card. */
  overviewDescription: string;
  /** Title of the Overview status-history card (default "Status history"). */
  historyTitle: string;
  events: readonly StatusEvent[];
  activity: readonly ActivityItem[];
  dangerActions: DangerZoneAction[];
  defaultTab: ResourceDetailTab;
  onTabChange: (tab: ResourceDetailTab) => void;
  onEditDetails: () => void;
  onSaveSettings: (settings: ResourceSettings) => void;
  /** Confirmed Danger zone action id (e.g. `pause`, `delete`). */
  onDangerAction: (actionId: string) => void | Promise<void>;
  shell: Omit<ConsoleShellProps, 'children'>;
}

const TABS: Array<{ value: ResourceDetailTab; label: string }> = [
  { value: 'overview', label: 'Overview' },
  { value: 'activity', label: 'Activity' },
  { value: 'settings', label: 'Settings' },
];

/** Resource detail: header with status and actions, then Overview / Activity / Settings tabs. */
export default function ResourceDetailPage({
  name = detailResource.name,
  description = detailResource.description,
  status = detailResource.status,
  breadcrumbs = detailBreadcrumbs,
  meta = detailMeta,
  actions = [
    { label: 'View logs', icon: FileText, variant: 'secondary' },
    { label: 'Redeploy', icon: RotateCw, variant: 'primary' },
  ],
  details = detailItems,
  overviewTitle = 'Configuration',
  overviewDescription = 'Settings of this resource.',
  historyTitle = 'Status history',
  events = detailEvents,
  activity = detailActivity,
  dangerActions = detailDangerActions,
  defaultTab = 'overview',
  onTabChange,
  onEditDetails,
  onSaveSettings,
  onDangerAction,
  shell,
}: Partial<ResourceDetailProps>) {
  const [tab, setTab] = useState<ResourceDetailTab>(defaultTab);
  const [settings, setSettings] = useState<ResourceSettings>({ name, description });
  const [saved, setSaved] = useState<ResourceSettings>({ name, description });
  const dirty = settings.name !== saved.name || settings.description !== saved.description;

  return (
    <ConsoleShell currentHref="/deployments" breadcrumbs={breadcrumbs} {...shell}>
      <Page
        width="wide"
        header={
          <PageHeader
            breadcrumbs={null}
            title={name}
            description={description}
            status={status}
            meta={meta}
            actions={actions}
            tabs={null}
          />
        }
      >
        <Tabs
          value={tab}
          onValueChange={(v) => {
            const next = TABS.find((t) => t.value === v)?.value ?? 'overview';
            setTab(next);
            onTabChange?.(next);
          }}
        >
          <TabsList aria-label="Resource sections">
            {TABS.map((t) => (
              <TabsTab key={t.value} value={t.value}>
                {t.label}
              </TabsTab>
            ))}
          </TabsList>

          <TabsPanel value="overview">
            <Grid cols={{ base: 1, lg: 5 }} gap={6} align="start">
              <DescriptionListCard
                className="lg:col-span-3"
                titleAs="h2"
                title={overviewTitle}
                description={overviewDescription}
                items={details}
                onEdit={onEditDetails}
              />
              <Section variant="card" padding="md" title={historyTitle} className="lg:col-span-2">
                <StatusTimeline events={events} maxVisible={4} />
              </Section>
            </Grid>
          </TabsPanel>

          <TabsPanel value="activity">
            <Section
              variant="card"
              padding="md"
              title="Activity"
              description="Changes made to this resource by people and automations."
            >
              <ActivityFeed items={activity} label="Activity, newest first" />
            </Section>
          </TabsPanel>

          <TabsPanel value="settings">
            <Stack gap={8}>
              <form
                noValidate
                onSubmit={(e) => {
                  e.preventDefault();
                  setSaved(settings);
                  onSaveSettings?.(settings);
                }}
              >
                <FormSection
                  title="General"
                  description="Name and description shown across the console."
                  actions={
                    <>
                      <Button variant="ghost" disabled={!dirty} onClick={() => setSettings(saved)}>
                        Discard
                      </Button>
                      <Button type="submit" disabled={!dirty}>
                        Save changes
                      </Button>
                    </>
                  }
                >
                  <Stack gap={4}>
                    <Field>
                      <FieldLabel required>Name</FieldLabel>
                      <Input
                        required
                        value={settings.name}
                        onValueChange={(v) => setSettings((s) => ({ ...s, name: v }))}
                      />
                      <FieldDescription>Lowercase letters, numbers and dashes.</FieldDescription>
                    </Field>
                    <Field>
                      <FieldLabel>Description</FieldLabel>
                      <Textarea
                        rows={3}
                        value={settings.description}
                        onValueChange={(v) => setSettings((s) => ({ ...s, description: v }))}
                      />
                    </Field>
                  </Stack>
                </FormSection>
              </form>
              <DangerZone
                description="These actions affect everyone who uses this resource."
                actions={dangerActions}
                onConfirm={onDangerAction}
              />
            </Stack>
          </TabsPanel>
        </Tabs>
      </Page>
    </ConsoleShell>
  );
}

import {
  DEPLOYMENT_DETAILS,
  DEPLOYMENT_EVENTS,
  PROJECT_ACTIVITY,
  type ActivityItem,
  type DangerZoneAction,
  type DescriptionItem,
  type PageHeaderMetaItem,
  type StatusEvent,
} from '@gntik-ai/blocks';
import { Clock, GitBranch, Globe } from '@gntik-ai/icons';
import type { BreadcrumbItem } from '@gntik-ai/ui';

/** The editable part of the resource (Settings tab). */
export interface ResourceSettings {
  name: string;
  description: string;
}

export const detailResource = {
  name: 'orders-api',
  status: 'running',
  description: 'Public REST API for orders, carts and checkout.',
} as const;

export const detailBreadcrumbs: BreadcrumbItem[] = [
  { label: 'Deployments', href: '/deployments' },
  { label: detailResource.name, mono: true },
];

export const detailMeta: PageHeaderMetaItem[] = [
  { label: 'Region', value: 'eu-west-1', icon: Globe, mono: true },
  { label: 'Branch', value: 'main', icon: GitBranch, mono: true },
  { label: 'Last deploy', value: '12 min ago', icon: Clock },
];
export const detailItems: DescriptionItem[] = DEPLOYMENT_DETAILS;
export const detailEvents: StatusEvent[] = DEPLOYMENT_EVENTS;
export const detailActivity: ActivityItem[] = PROJECT_ACTIVITY;

export const detailDangerActions: DangerZoneAction[] = [
  {
    id: 'pause',
    title: 'Pause deployment',
    description: 'Stops serving traffic until you resume it. Configuration is kept.',
    actionLabel: 'Pause',
    destructive: false,
  },
  {
    id: 'delete',
    title: 'Delete deployment',
    description: `Permanently deletes ${detailResource.name}, its secrets and history. This cannot be undone.`,
    actionLabel: 'Delete deployment',
    confirmText: detailResource.name,
  },
];

import {
  AppSidebarFooter,
  AppSidebarHeader,
  AppSidebarNav,
  AppTopbar,
  type AppSidebarFooterProps,
  type AppSidebarHeaderProps,
  type AppTopbarProps,
} from '@gntik-ai/blocks';
import {
  SidebarLayout,
  type BreadcrumbItem,
  type NavGroup,
  type SidebarLayoutProps,
  type UserMenuUser,
  type Workspace,
} from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface ConsoleShellProps
  extends
    Pick<AppSidebarHeaderProps, 'currentWorkspaceId' | 'onWorkspaceChange' | 'onCreateWorkspace'>,
    Pick<AppSidebarFooterProps, 'usage' | 'helpHref' | 'helpLabel' | 'userMenuItems' | 'onSignOut'>,
    Pick<SidebarLayoutProps, 'sidebarLabel' | 'collapseMode'> {
  /** Page content (usually a <Page>). */
  children: ReactNode;
  /** Sidebar navigation; defaults to the AppSidebar sample groups. */
  nav?: NavGroup[];
  /** Href of the current page, marks the active nav item. */
  currentHref?: string;
  breadcrumbs?: BreadcrumbItem[] | null;
  workspaces?: Workspace[] | null;
  user?: UserMenuUser | null;
  /** Extra AppTopbar props (environment, notifications, theme control…). */
  topbar?: Omit<AppTopbarProps, 'breadcrumbs' | 'user'>;
  /** localStorage key for the collapsed sidebar; `undefined` disables persistence. */
  storageKey?: string;
}

/**
 * The console frame shared by the templates: SidebarLayout with the AppSidebar header, nav and
 * footer, and the AppTopbar (breadcrumb, ⌘K search, notifications, theme, user menu).
 * Templates fill it with a Page; products swap the nav, workspaces, user, usage meter, help
 * link and user-menu items.
 */
export function ConsoleShell({
  children,
  nav,
  currentHref,
  breadcrumbs,
  workspaces,
  currentWorkspaceId,
  onWorkspaceChange,
  onCreateWorkspace,
  user,
  usage,
  helpHref,
  helpLabel,
  userMenuItems,
  onSignOut,
  topbar,
  storageKey,
  sidebarLabel,
  collapseMode,
}: ConsoleShellProps) {
  return (
    <SidebarLayout
      fullScreen
      storageKey={storageKey}
      sidebarLabel={sidebarLabel}
      collapseMode={collapseMode}
      sidebarHeader={({ collapsed }) => (
        <AppSidebarHeader
          collapsed={collapsed}
          workspaces={workspaces}
          currentWorkspaceId={currentWorkspaceId}
          onWorkspaceChange={onWorkspaceChange}
          onCreateWorkspace={onCreateWorkspace}
        />
      )}
      sidebar={({ collapsed }) => <AppSidebarNav groups={nav} currentHref={currentHref} collapsed={collapsed} />}
      sidebarFooter={({ collapsed }) => (
        <AppSidebarFooter
          collapsed={collapsed}
          user={user}
          usage={usage}
          helpHref={helpHref}
          helpLabel={helpLabel}
          userMenuItems={userMenuItems}
          onSignOut={onSignOut}
        />
      )}
      topbar={<AppTopbar breadcrumbs={breadcrumbs} user={user} {...topbar} />}
    >
      {children}
    </SidebarLayout>
  );
}
